<?php
namespace App\Http\Controllers;
use App\Models\{Invoice,InvoiceItem,Patient,Payment,Service};use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Validation\Rule;
class BillingController extends Controller {
 public function index(){ $invoices=Invoice::with(['patient','payments'])->latest()->paginate(15);return view('billing.index',compact('invoices'));}
 public function create(){return view('billing.form',['patients'=>Patient::orderBy('name')->get(),'services'=>Service::where('active',true)->get()]);}
 public function store(Request $r){$d=$r->validate(['patient_id'=>'required|exists:patients,id','service_id'=>'nullable|exists:services,id','description'=>'required|string|max:180','quantity'=>'required|integer|min:1|max:100','unit_price'=>'required|numeric|min:0','discount'=>'nullable|numeric|min:0','payment_amount'=>'nullable|numeric|min:0','method'=>['required_with:payment_amount',Rule::in(['Cash','Card','Mobile Money'])]]);$invoice=DB::transaction(function()use($d,$r){$subtotal=$d['quantity']*$d['unit_price'];$discount=min($subtotal,$d['discount']??0);$i=Invoice::create(['invoice_number'=>'INV-'.now()->format('YmdHis').'-'.strtoupper(\Illuminate\Support\Str::random(3)),'patient_id'=>$d['patient_id'],'subtotal'=>$subtotal,'discount'=>$discount,'total'=>$subtotal-$discount,'status'=>'Unpaid']);InvoiceItem::create(['invoice_id'=>$i->id,'service_id'=>$d['service_id']??null,'description'=>$d['description'],'quantity'=>$d['quantity'],'unit_price'=>$d['unit_price'],'total'=>$subtotal]);if(($d['payment_amount']??0)>0){$amount=min($d['payment_amount'],$i->total);$i->payments()->create(['receipt_number'=>'RCT-'.now()->format('YmdHis').'-'.strtoupper(\Illuminate\Support\Str::random(3)),'amount'=>$amount,'method'=>$d['method'],'received_by'=>$r->user()->id,'paid_at'=>now()]);}$i->update(['status'=>$i->balance<=0?'Paid':($i->paid>0?'Partially Paid':'Unpaid')]);return $i;});return redirect()->route('billing.index')->with('success','Invoice created.');}
 public function payment(Request $r,Invoice $invoice){$d=$r->validate(['amount'=>'required|numeric|min:0.01','method'=>['required',Rule::in(['Cash','Card','Mobile Money'])]]);abort_if($d['amount']>$invoice->balance,422,'Payment exceeds the remaining balance.');DB::transaction(function()use($d,$r,$invoice){$invoice->payments()->create(['receipt_number'=>'RCT-'.now()->format('YmdHis').'-'.strtoupper(\Illuminate\Support\Str::random(3)),'amount'=>$d['amount'],'method'=>$d['method'],'received_by'=>$r->user()->id,'paid_at'=>now()]);$invoice->refresh();$invoice->update(['status'=>$invoice->balance<=0?'Paid':'Partially Paid']);});return back()->with('success','Payment recorded.');}
 public function show(Invoice $invoice){$invoice->load(['patient','items','payments']);return view('billing.show',compact('invoice'));}
}
